/* Model visual and motion records indexed by the native unit model ID.
 * The three trailing reserved words are zero in each row. */

/* Initialize the se_no word view with its native little-endian fields.
 * The final byte is signed, like the motion lookup uses it. */
#define MOTION_SOUND(low, high, type, data) \
    { (low) + (high) * 0x100 + (type) * 0x10000 + (data) * 0x1000000 }

